-- validation_queries.sql - post-deployment smoke checks
-- 1. All story tasks were seeded.
SELECT COUNT(*) AS seeded_tasks FROM aerospace_parts_inventory_2_db.core.story_tasks;

-- 2. No NULL task names.
SELECT COUNT(*) AS null_task_names FROM aerospace_parts_inventory_2_db.core.story_tasks WHERE task_name IS NULL;

-- 3. Every requirement has a traceability row.
SELECT COUNT(*) AS untraced FROM aerospace_parts_inventory_2_db.core.requirements_traceability WHERE test_id IS NULL;

-- 4. Test results summary.
SELECT result, COUNT(*) AS tests FROM aerospace_parts_inventory_2_db.core.test_results GROUP BY result;

-- 5. Deployment audit entries exist.
SELECT stage, action, logged_at FROM aerospace_parts_inventory_2_db.core.deployment_audit ORDER BY logged_at;

-- 6. Coverage distribution.
SELECT * FROM aerospace_parts_inventory_2_db.core.v_requirements_coverage;
